class Notifier:
    def send(self, user, text):
        raise NotImplementedError


class SmsNotifier(Notifier):
    def send(self, user, text):
        return [f"SMS to {user}: {text}"]


class EmailNotifier(Notifier):
    def send(self, user, text):
        return [f"Email to {user}: {text}"]


class SmsAndEmailNotifier(SmsNotifier):          # one class per combination...
    def send(self, user, text):
        return super().send(user, text) + [f"Email to {user}: {text}"]


print(SmsAndEmailNotifier().send("Aditi", "Mess closed tonight"))
print("classes needed for 3 channels, every combination:", 2 ** 3 - 1)

class Sms:
    def deliver(self, user, text):
        return f"SMS to {user}: {text}"


class Email:
    def deliver(self, user, text):
        return f"Email to {user}: {text}"


class WhatsApp:
    def deliver(self, user, text):
        return f"WhatsApp to {user}: {text}"


class QuietHours:                                   # a wrapper adds behaviour to any channel
    def __init__(self, channel, hour):
        self.channel, self.hour = channel, hour

    def deliver(self, user, text):
        if 22 <= self.hour or self.hour < 7:
            return f"(held until 7 am) {self.channel.deliver(user, text)}"
        return self.channel.deliver(user, text)


class Notifier:
    def __init__(self, channels):
        self.channels = list(channels)              # has-a: any mix, chosen at runtime

    def send(self, user, text):
        return [c.deliver(user, text) for c in self.channels]


warden = Notifier([Sms(), Email()])
for line in warden.send("Aditi", "Mess closed tonight"):
    print(line)
night = Notifier([QuietHours(WhatsApp(), hour=23)])
print(night.send("Bilal", "Water off at 6 am")[0])

